import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import LandingNavbar from '../components/LandingNavbar';
import Navbar from '../components/Navbar';

const Artists = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const { user } = useSelector((state) => state.auth);

  // Dummy data for demonstration
  const artists = [
    {
      id: 1,
      name: 'Jean Paul Mugisha',
      specialty: 'Traditional Painting',
      bio: 'Specializing in traditional Rwandan art forms, bringing cultural heritage to life through vibrant colors.',
      image: 'https://picsum.photos/200/200',
      artworks: 24,
      followers: 1200,
    },
    {
      id: 2,
      name: 'Marie Claire Uwase',
      specialty: 'Digital Art',
      bio: 'Contemporary digital artist blending modern techniques with traditional Rwandan motifs.',
      image: 'https://picsum.photos/200/201',
      artworks: 18,
      followers: 890,
    },
    {
      id: 3,
      name: 'Emmanuel Kwizera',
      specialty: 'Sculpture',
      bio: 'Creating powerful sculptures that tell stories of Rwanda\'s past and present.',
      image: 'https://picsum.photos/200/202',
      artworks: 15,
      followers: 750,
    },
    {
      id: 4,
      name: 'Alice Mukamana',
      specialty: 'Mixed Media',
      bio: 'Exploring the intersection of traditional and contemporary art through mixed media.',
      image: 'https://picsum.photos/200/203',
      artworks: 30,
      followers: 1500,
    },
  ];

  const filteredArtists = artists.filter(artist =>
    artist.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    artist.specialty.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-cream">
      {user ? <Navbar userType={user.role.toLowerCase()} /> : <LandingNavbar />}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <h1 className="text-3xl font-bold text-brown mb-8">Artists</h1>

        {/* Search Section */}
        <div className="mb-8">
          <input
            type="text"
            placeholder="Search artists..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full px-4 py-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
          />
        </div>

        {/* Artists Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {filteredArtists.map((artist) => (
            <div key={artist.id} className="bg-white rounded-lg shadow-md overflow-hidden">
              <img
                src={artist.image}
                alt={artist.name}
                className="w-full h-48 object-cover"
              />
              <div className="p-4">
                <h3 className="text-lg font-semibold text-brown">{artist.name}</h3>
                <p className="text-brown/70 mb-2">{artist.specialty}</p>
                <p className="text-brown/80 text-sm mb-4">{artist.bio}</p>
                <div className="flex justify-between items-center text-sm text-brown/60">
                  <span>{artist.artworks} Artworks</span>
                  <span>{artist.followers} Followers</span>
                </div>
                <Link
                  to="/login"
                  className="mt-4 block w-full text-center bg-coral text-white py-2 rounded-lg hover:bg-salmon transition-colors"
                >
                  View Profile
                </Link>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Artists;
